451	/// Accumulates one run's semantic items as [`SessionEvent`]s for the runner to
452	/// persist at run exit.
453	///
454	/// The runner pre-seeds the recorder with the run's `AgentInput` messages (the
455	/// new turn — which the agent does not re-emit on its event stream), then feeds
456	/// it every [`crate::AgentEvent`] as the stream flows. [`SessionRecorder::drain`]
457	/// returns the accumulated log, synthesizing a [`SessionEvent::ToolReturned`]
458	/// for any tool call left without a result (a run interrupted mid-tool) so the
459	/// log always [`project`]s to a provider-valid conversation. A deferred call
460	/// gets no synthetic result: it waits for a host decision.
461	///
462	/// On a resume ([`SessionRecorder::with_resume_plan`]), the results of the
463	/// resumed calls go before the recorded input. If the agent rejects the resume
464	/// before it gives a result for a resumed call, the recorder records nothing,
465	/// and the deferrals stay open.
466	#[derive(Debug)]
467	pub struct SessionRecorder {
468	    events: Vec<SessionEvent>,
469	    current_agent: String,
470	    deferral_slot: Option<crate::DeferralSlot>,
471	    /// The call ids of the resumed calls (empty when the run is no resume).
472	    resume_call_ids: Vec<String>,
473	    /// The tool results that the agent emits before its first turn.
474	    resume_block: Vec<SessionEvent>,
475	    /// `true` until the first `TurnStarted` of a resumed run.
476	    in_resume_window: bool,
477	    /// `true` when the agent rejected the resume: a `RunFailed` came in the
478	    /// resume window before a result for a resumed call.
479	    resume_rejected: bool,
480	}
481	
482	impl SessionRecorder {
483	    /// Create a recorder seeded with the root agent's name. Used to attribute
484	    /// assistant messages whose [`Item::AssistantMessage`] `agent` is `None`,
485	    /// before any `RunStarted`/`AgentUpdated` updates the tracked agent.
486	    pub fn new(root_agent: impl Into<String>) -> Self {
487	        Self {
488	            events: Vec::new(),
489	            current_agent: root_agent.into(),
490	            deferral_slot: None,
491	            resume_call_ids: Vec::new(),
492	            resume_block: Vec::new(),
493	            in_resume_window: false,
494	            resume_rejected: false,
495	        }
496	    }
497	
498	    /// Wire the resume plan of a resumed run.
499	    ///
500	    /// The runner records the new input before the stream starts, but the
501	    /// results of the resumed calls must come before that input in the log.
502	    /// So the recorder keeps every tool result that the agent emits before its
503	    /// first `TurnStarted` apart, and [`SessionRecorder::drain`] puts these
504	    /// results first. A resumed call with no result gets the synthetic
505	    /// cancel result in the same place, so the deferral is closed.
506	    ///
507	    /// The one exception is a rejected resume. An agent that cannot resume
508	    /// (for example a workflow agent) emits `RunFailed` before it gives a
509	    /// result for a resumed call. No resumed call started, so
510	    /// [`SessionRecorder::drain`] then returns no events: the session keeps
511	    /// its open deferrals, and a later resume can still resolve them. An
512	    /// `LlmAgent` that ends before it runs the calls gives a "did not run"
513	    /// result for each call before its `RunFailed`, so this exception does
514	    /// not apply to it. A cancel or a timeout emits no `RunFailed`, so a
515	    /// resumed call that started still gets the synthetic cancel result.
516	    #[must_use]
517	    pub fn with_resume_plan(mut self, plan: &crate::ResumePlan) -> Self {
518	        self.resume_call_ids = plan.call_ids();
519	        self.in_resume_window = true;
520	        self
521	    }
522	
523	    /// Wire the run's deferral slot. The slot holds the raw arguments of the
524	    /// deferred calls. The recorder persists these raw arguments in
525	    /// [`SessionEvent::ToolDeferred`], because the resume runs the tool with
526	    /// exactly these arguments. The arguments in [`AgentEvent::RunDeferred`]
527	    /// can be redacted.
528	    #[must_use]
529	    pub fn with_deferral_slot(mut self, slot: crate::DeferralSlot) -> Self {
530	        self.deferral_slot = Some(slot);
531	        self
532	    }
533	
534	    /// Record the run's input messages (the new turn). The agent never re-emits
535	    /// these on its event stream, so the runner records them directly.
536	    /// [`Item::System`] has no [`SessionEvent`] equivalent and is skipped.
537	    pub fn record_input(&mut self, messages: &[Item]) {
538	        for item in messages {
539	            match item {
540	                Item::UserMessage { content } => {
541	                    self.events
542	                        .push(SessionEvent::user_message(content.clone()));
543	                }
544	                Item::AssistantMessage { content, agent } => {
545	                    let name = agent.clone().unwrap_or_else(|| self.current_agent.clone());
546	                    self.events
547	                        .push(SessionEvent::assistant_message(content.clone(), name));
548	                }
549	                Item::ToolCall {
550	                    call_id,
551	                    name,
552	                    args,
553	                } => {
554	                    self.events.push(SessionEvent::tool_called(
555	                        call_id.clone(),
556	                        name.clone(),
557	                        args.clone(),
558	                    ));
559	                }
560	                Item::ToolResult { call_id, content } => {
561	                    self.events.push(SessionEvent::tool_returned(
562	                        call_id.clone(),
563	                        content.clone(),
564	                    ));
565	                }
566	                Item::System { .. } => {
567	                    tracing::debug!(
568	                        target: "paigasus::core::session",
569	                        "SessionRecorder: skipping Item::System in input (no SessionEvent variant)"
570	                    );
571	                }
572	            }
573	        }
574	    }
575	
576	    /// Observe one [`crate::AgentEvent`] from the run's stream: record the
577	    /// semantic items (assistant messages, tool calls, tool results, handoffs)
578	    /// and track the active agent from `RunStarted` / `AgentUpdated`.
579	    pub fn observe(&mut self, event: &AgentEvent) {
580	        match event {
581	            AgentEvent::RunStarted { agent } | AgentEvent::AgentUpdated { agent } => {
582	                self.current_agent = agent.clone();
583	            }
584	            AgentEvent::TurnStarted { .. } => {
585	                self.in_resume_window = false;
586	            }
587	            AgentEvent::RunFailed { .. } if self.in_resume_window && !self.has_resume_result() => {
588	                self.resume_rejected = true;
589	            }
590	            AgentEvent::MessageOutput {
591	                item: Item::AssistantMessage { content, agent },
592	            } => {
593	                let name = agent.clone().unwrap_or_else(|| self.current_agent.clone());
594	                self.events
595	                    .push(SessionEvent::assistant_message(content.clone(), name));
596	            }
597	            AgentEvent::ToolCallItem {
598	                item:
599	                    Item::ToolCall {
600	                        call_id,
601	                        name,
602	                        args,
603	                    },
604	            } => {
605	                self.events.push(SessionEvent::tool_called(
606	                    call_id.clone(),
607	                    name.clone(),
608	                    args.clone(),
609	                ));
610	            }
611	            AgentEvent::ToolOutputItem {
612	                item: Item::ToolResult { call_id, content },
613	            } => {
614	                let event = SessionEvent::tool_returned(call_id.clone(), content.clone());
615	                if self.in_resume_window {
616	                    self.resume_block.push(event);
617	                } else {
618	                    self.events.push(event);
619	                }
620	            }
621	            AgentEvent::HandoffItem { from, to } => {
622	                self.events
623	                    .push(SessionEvent::handoff_occurred(from.clone(), to.clone()));
624	            }
625	            AgentEvent::RunDeferred { calls, .. } => {
626	                let mut warned = false;
627	                for call in calls {
628	                    let raw = self
629	                        .deferral_slot
630	                        .as_ref()
631	                        .and_then(|slot| slot.take(call.deferral_id()));
632	                    match raw {
633	                        Some(raw) => self.events.push(SessionEvent::tool_deferred(&raw)),
634	                        None => {
635	                            if !warned {
636	                                warned = true;
637	                                tracing::warn!(
638	                                    target: "paigasus::core::session",
639	                                    "RunDeferred call has no raw arguments in the deferral slot; recording the event copy, whose arguments can be redacted"
640	                                );
641	                            }
642	                            self.events.push(SessionEvent::tool_deferred(call));
643	                        }
644	                    }
645	                }
646	            }
647	            AgentEvent::UserMessageInjected { content } => {
648	                self.events
649	                    .push(SessionEvent::user_message(content.clone()));
650	            }
651	            _ => {}
652	        }
653	    }
654	
655	    /// Drain the accumulated events, appending a synthesized
656	    /// [`SessionEvent::ToolReturned`] for every [`SessionEvent::ToolCalled`]
657	    /// left without a matching result (a run cancelled/timed out mid-tool).
658	    /// The returned log always [`project`]s to a provider-valid conversation.
659	    ///
660	    /// On a resume, the log starts with the results of the resumed calls (and
661	    /// a synthesized result for each resumed call without one), then the
662	    /// recorded input and run events. A rejected resume returns no events.
663	    ///
664	    /// The match is by position, because a call id can repeat in one run: a
665	    /// `ToolCalled` event is closed only by a later `ToolReturned` (or
666	    /// `ToolDeferred`) event with the same call id, and each later event
667	    /// closes one call.
668	    pub fn drain(&mut self) -> Vec<SessionEvent> {
669	        if std::mem::take(&mut self.resume_rejected) {
670	            // A rejected resume: record nothing, so the deferrals stay open
671	            // and no input follows them (see `with_resume_plan`).
672	            self.resume_block.clear();
673	            self.resume_call_ids.clear();
674	            self.events.clear();
675	            return Vec::new();
676	        }
677	        let mut out = std::mem::take(&mut self.resume_block);
678	        let mut answered: Vec<String> = out
679	            .iter()
680	            .filter_map(|e| match e {
681	                SessionEvent::ToolReturned { call_id, .. } => Some(call_id.clone()),
682	                _ => None,
683	            })
684	            .collect();
685	        for call_id in std::mem::take(&mut self.resume_call_ids) {
686	            match answered.iter().position(|a| *a == call_id) {
687	                Some(p) => {
688	                    answered.remove(p);
689	                }
690	                None => out.push(cancelled_result(call_id)),
691	            }
692	        }
693	        out.append(&mut self.events);
694	
695	        let mut unanswered: Vec<String> = Vec::new();
696	        for e in &out {
697	            match e {
698	                SessionEvent::ToolCalled { call_id, .. } => unanswered.push(call_id.clone()),
699	                SessionEvent::ToolReturned { call_id, .. }
700	                | SessionEvent::ToolDeferred { call_id, .. } => {
701	                    if let Some(p) = unanswered.iter().position(|c| c == call_id) {
702	                        unanswered.remove(p);
703	                    }
704	                }
705	                _ => {}
706	            }
707	        }
708	        out.extend(unanswered.into_iter().map(cancelled_result));
709	        out
710	    }
711	}
712	
713	impl SessionRecorder {
714	    /// Whether the resume block holds a result for a resumed call.
715	    fn has_resume_result(&self) -> bool {
716	        self.resume_block.iter().any(|e| {
717	            matches!(e, SessionEvent::ToolReturned { call_id, .. }
718	                if self.resume_call_ids.contains(call_id))
719	        })
720	    }
721	}
722	
723	/// The synthetic result for a tool call that a run left without a result.
724	fn cancelled_result(call_id: String) -> SessionEvent {
725	    SessionEvent::tool_returned(
726	        call_id,
727	        vec![ContentPart::Text {
728	            text: "tool call did not complete (run cancelled/timed out)".to_owned(),
729	        }],
730	    )
731	}
