713	impl SessionRecorder {
714	    /// Whether the resume block holds a result for a resumed call.
715	    fn has_resume_result(&self) -> bool {
716	        self.resume_block.iter().any(|e| {
717	            matches!(e, SessionEvent::ToolReturned { call_id, .. }
718	                if self.resume_call_ids.contains(call_id))
719	        })
720	    }
721	}
