1	//! [`CompactingSession`] — a [`Session`] wrapper that LLM-summarizes the log
2	//! once a token threshold is exceeded. See spec §4.2.
3	
4	use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
5	use std::sync::Arc;
6	
7	use async_trait::async_trait;
8	use futures_util::StreamExt;
9	
10	use crate::{
11	    open_deferrals, project, CancellationToken, ContentPart, ConversationSnapshot,
12	    HeuristicTokenCounter, Item, Model, ModelEvent, ModelRequest, ModelSettings, SequenceId,
13	    Session, SessionError, SessionEvent, TokenCounter,
14	};
15	
16	const DEFAULT_PROMPT: &str = "Summarize the conversation so far into a concise summary, \
17	preserving key facts, decisions, and open questions.";
18	/// Default threshold (tokens). Chosen with headroom under common context windows.
19	const DEFAULT_THRESHOLD: usize = 8_000;
