21	/// A [`Session`] that wraps any inner session and triggers LLM-based
22	/// compaction once the projected token count exceeds `threshold`.
23	///
24	/// **Single logical writer per session** (spec §4.2): the inner backend stays
25	/// durable under concurrency, but the compaction bookkeeping assumes appends
26	/// through this wrapper are serialized. `threshold` must sit below the
27	/// summarization model's context window, and the model should produce
28	/// summaries shorter than `threshold`, for compaction to converge.
29	pub struct CompactingSession<S> {
30	    inner: S,
31	    model: Arc<dyn Model>,
32	    counter: Arc<dyn TokenCounter>,
33	    threshold: usize,
34	    settings: ModelSettings,
35	    prompt: String,
36	    cheap_estimate: AtomicUsize,
37	    compacting: AtomicBool,
38	}
