114	    pub fn build(self) -> Result<CompactingSession<S>, CompactingSessionError> {
115	        if self.threshold == 0 {
116	            return Err(CompactingSessionError::ZeroThreshold);
117	        }
118	        Ok(CompactingSession {
119	            inner: self.inner,
120	            model: self.model,
121	            counter: self
122	                .counter
123	                .unwrap_or_else(|| Arc::new(HeuristicTokenCounter)),
124	            threshold: self.threshold,
125	            settings: self.settings,
126	            prompt: self.prompt,
127	            // usize::MAX forces the first maybe_compact to take the authoritative
128	            // path and seed from the (possibly pre-populated) inner log.
129	            cheap_estimate: AtomicUsize::new(usize::MAX),
130	            compacting: AtomicBool::new(false),
131	        })
132	    }
