135	/// RAII reset for the single-flight `compacting` flag — constructed only on the
136	/// swap-won path, so it never clears a flag it did not set.
137	struct CompactGuard<'a>(&'a AtomicBool);
138	impl Drop for CompactGuard<'_> {
139	    fn drop(&mut self) {
140	        self.0.store(false, Ordering::Release);
141	    }
142	}
