551	/// The log index `k_i` of the `HandoffOccurred` event into `path[i]` for each
552	/// level `i` (`k_0 = 0`), all before `deferred_at`.
553	///
554	/// The search runs from the deepest level back to the root: `k_i` is the last
555	/// matching handoff before `k_{i+1}`. So a path that visits an agent two times
556	/// finds the handoffs of the latest chain.
557	fn handoff_indices(
558	    events: &[crate::SessionEvent],
559	    path: &[String],
560	    deferred_at: usize,
561	) -> Result<Vec<usize>, InvalidResume> {
562	    use crate::SessionEvent;
563	    let mut indices = vec![0; path.len()];
564	    let mut upper = deferred_at;
565	    for level in (1..path.len()).rev() {
566	        let k = events[..upper]
567	            .iter()
568	            .rposition(|e| {
569	                matches!(e, SessionEvent::HandoffOccurred { from, to, .. }
570	                    if *from == path[level - 1] && *to == path[level])
571	            })
572	            .ok_or(InvalidResume::SessionModified)?;
573	        indices[level] = k;
574	        upper = k;
575	    }
576	    Ok(indices)
577	}
