579	/// `view(level, end)`: the conversation of `path[level]` over `events[..end]`.
580	///
581	/// `view(0, end)` is the projection of `events[..end]`. A child view threads
582	/// the parent view at its handoff (no tool items, plus a transfer note) and
583	/// then adds the projection of the events after the handoff.
584	///
585	/// A child view pairs each tool result with one open call of the view: the
586	/// result closes the earliest open call with its call id. The view drops a
587	/// result that closes no open call. The session recorder closes the
588	/// transfer calls of a run with a synthetic result after the handoff, and
589	/// the child view has no transfer call. A child call can use the call id of
590	/// a transfer call, so a match by call id alone can keep two results for one
591	/// call.
592	fn agent_view(
593	    events: &[crate::SessionEvent],
594	    handoffs: &[usize],
595	    level: usize,
596	    end: usize,
597	) -> Vec<crate::Item> {
598	    use crate::Item;
599	    if level == 0 {
600	        return crate::project(&events[..end]).messages;
601	    }
602	    let k = handoffs[level];
603	    let mut view =
604	        crate::loop_state::thread_handoff_transcript(&agent_view(events, handoffs, level - 1, k));
605	    view.extend(crate::project(&events[k + 1..end]).messages);
606	    // The call ids of the open calls, in view order.
607	    let mut open: Vec<String> = Vec::new();
608	    view.retain(|item| match item {
609	        Item::ToolCall { call_id, .. } => {
610	            open.push(call_id.clone());
611	            true
612	        }
613	        Item::ToolResult { call_id, .. } => match open.iter().position(|c| c == call_id) {
614	            Some(p) => {
615	                open.remove(p);
616	                true
617	            }
618	            None => false,
619	        },
620	        _ => true,
621	    });
622	    view
623	}
