145	/// or the resumed results), and other runs ignore it (best-effort).
146	async fn finalize(
147	    session: &Arc<dyn Session>,
148	    recorder: &Arc<Mutex<SessionRecorder>>,
149	) -> Result<(), SessionError> {
150	    let events = recorder
151	        .lock()
152	        .expect("session recorder mutex poisoned")
153	        .drain();
154	    let result = session.append(&events).await;
155	    if let Err(e) = &result {
156	        tracing::warn!(
157	            target: "paigasus::runtime_tokio::runner",
158	            error = %e,
159	            "session persistence failed during finalize"
160	        );
161	    }
162	    result
163	}
