1	//! [`Vec<Item>`] → OpenAI Chat / Responses request messages.
2	//!
3	//! See SMA-316 spec § "Wire translation" for the rule table. Both backends
4	//! share many translation rules but the output JSON shape differs; we
5	//! build serde_json `Value`s directly rather than typed structs to keep
6	//! the test-fixture surface readable.
7	
8	use paigasus_helikon_core::{ContentPart, Item, MediaSource};
9	use serde_json::{json, Value};
10	
11	/// Translate a conversation `Vec<Item>` into OpenAI Chat Completions
12	/// `messages: [...]` form.
13	///
14	/// Rules per the SMA-316 spec's Wire translation § Chat Completions
15	/// table. Notably:
16	/// - Standalone `Item::ToolCall`s (no preceding `AssistantMessage` in
17	///   the same turn) are gathered into a synthesized
18	///   `{role: "assistant", content: null, tool_calls: [...]}`.
19	/// - `UserMessage` containing `ContentPart::ToolResult` (Anthropic
20	///   nested shape) hoists those parts into top-level `tool` messages.
21	/// - `ContentPart::Image`/`Audio` inside an `AssistantMessage` are
22	///   dropped with `tracing::warn!` (Chat assistant role accepts
23	///   string-or-null only).
24	/// - `ContentPart::Reasoning` is dropped (OpenAI Chat does not accept
25	///   reasoning input).
26	pub(crate) fn to_chat_messages(items: &[Item]) -> Value {
27	    let mut out: Vec<Value> = Vec::new();
28	    let mut pending_tool_calls: Vec<Value> = Vec::new();
29	
30	    fn flush_pending(out: &mut Vec<Value>, pending: &mut Vec<Value>) {
31	        if !pending.is_empty() {
32	            out.push(json!({
33	                "role": "assistant",
34	                "content": Value::Null,
35	                "tool_calls": std::mem::take(pending),
36	            }));
37	        }
38	    }
39	
40	    for item in items {
41	        match item {
42	            Item::System { content } => {
43	                flush_pending(&mut out, &mut pending_tool_calls);
44	                out.push(json!({"role": "system", "content": text_of(content)}));
45	            }
46	            Item::UserMessage { content } => {
47	                flush_pending(&mut out, &mut pending_tool_calls);
48	                emit_user_or_hoist(content, &mut out);
49	            }
50	            Item::AssistantMessage { content, agent: _ } => {
51	                flush_pending(&mut out, &mut pending_tool_calls);
52	                out.push(assistant_message(content));
53	            }
54	            Item::ToolCall {
55	                call_id,
