244	/// Runs sub-agents concurrently (cooperative `futures::stream::select_all` — core
245	/// has no tokio runtime), interleaving their events live. Each branch is keyed;
246	/// on completion its final text is written to `state[key]` (disjoint keys → safe).
247	///
248	/// `final_output` is deterministic: a synthesized terminal `MessageOutput` carrying
249	/// a sorted-key JSON object `{key: branch_output}` is emitted before the outer
250	/// `RunCompleted`. Per-branch results are addressed individually via `state[key]`.
251	/// Failure is **collect-all**: child `RunFailed` events are swallowed, siblings
252	/// finish, and one aggregate `RunFailed` is emitted.
253	///
254	/// Cooperative concurrency suits IO-bound `model.invoke`; a CPU-bound branch would
255	/// starve siblings between `.await` points. This is not OS-thread parallelism.
256	pub struct ParallelAgent<Ctx> {
257	    name: String,
258	    description: String,
259	    branches: Vec<(String, Arc<dyn Agent<Ctx>>)>,
260	}
261	
262	impl<Ctx> ParallelAgent<Ctx>
263	where
264	    Ctx: Send + Sync + 'static,
265	{
266	    /// Construct an empty parallel block.
267	    pub fn new(name: impl Into<String>, description: impl Into<String>) -> Self {
268	        Self {
269	            name: name.into(),
270	            description: description.into(),
271	            branches: Vec::new(),
272	        }
273	    }
274	
275	    /// Add a branch keyed by the agent's own name.
276	    #[allow(clippy::should_implement_trait)]
277	    pub fn add(mut self, agent: impl Agent<Ctx> + 'static) -> Self {
278	        let key = agent.name().to_owned();
279	        self.branches.push((key, Arc::new(agent)));
280	        self
281	    }
282	
283	    /// Add a branch with an explicit state key.
284	    pub fn branch(mut self, key: impl Into<String>, agent: impl Agent<Ctx> + 'static) -> Self {
285	        self.branches.push((key.into(), Arc::new(agent)));
286	        self
287	    }
288	
289	    /// Add a pre-wrapped branch keyed by the agent's name.
290	    pub fn add_shared(mut self, agent: Arc<dyn Agent<Ctx>>) -> Self {
291	        let key = agent.name().to_owned();
292	        self.branches.push((key, agent));
293	        self
294	    }
295	}
296	
297	#[async_trait]
298	impl<Ctx> Agent<Ctx> for ParallelAgent<Ctx>
299	where
300	    Ctx: Send + Sync + 'static,
301	{
302	    fn name(&self) -> &str {
303	        &self.name
304	    }
305	    fn description(&self) -> &str {
306	        &self.description
307	    }
308	
309	    async fn run(
310	        &self,
311	        ctx: RunContext<Ctx>,
312	        input: AgentInput,
313	    ) -> Result<BoxStream<'static, AgentEvent>, AgentError> {
314	        let name = self.name.clone();
315	        let branches = self.branches.clone();
316	
317	        let stream = async_stream::stream! {
318	            let parent_failure = ctx.failure_handle();
319	            let span = workflow_run_span(&name, ctx.tracer());
320	            yield AgentEvent::RunStarted { agent: name.clone() };
321	
322	            if crate::workflow::has_resume_input(&input) {
323	                parent_failure.set(AgentError::Other(anyhow::anyhow!(
324	                    "this agent cannot resume deferred calls"
325	                )));
326	                span.record("otel.status_code", "ERROR");
327	                yield AgentEvent::RunFailed {
328	                    error: "this agent cannot resume deferred calls".to_owned(),
329	                };
330	                return;
331	            }
332	
333	            let max = max_depth(ctx.run_config());
334	            if ctx.agent_depth() + 1 > max {
335	                let err = AgentError::MaxAgentDepthExceeded { depth: ctx.agent_depth() + 1, max };
336	                let msg = err.to_string();
337	                parent_failure.set(err);
338	                span.record("otel.status_code", "ERROR");
339	                yield AgentEvent::RunFailed { error: msg };
340	                return;
341	            }
342	
343	            // Start every branch; tag its stream with the branch index.
344	            let mut tagged: Vec<BoxStream<'static, (usize, AgentEvent)>> = Vec::new();
345	            let mut failures: Vec<crate::FailureSlot> = Vec::new();
346	            // Branch keys must be unique: parallel branches write concurrently, so
347	            // a duplicate key would be clobbered by completion order (nondeterministic).
348	            // Fail fast before starting any branch, mirroring the handoff tool-name
349	            // collision guard in the LlmAgent driver.
350	            let mut seen_keys = std::collections::HashSet::new();
351	            for (i, (key, agent)) in branches.iter().enumerate() {
352	                if !seen_keys.insert(key.clone()) {
353	                    let err = AgentError::Other(anyhow::anyhow!(
354	                        "duplicate parallel branch key: {key}"
355	                    ));
356	                    let msg = err.to_string();
357	                    parent_failure.set(err);
358	                    span.record("otel.status_code", "ERROR");
359	                    yield AgentEvent::RunFailed { error: msg };
360	                    return;
361	                }
362	                let child = ctx.subagent_child();
363	                failures.push(child.failure_handle());
364	                yield AgentEvent::AgentUpdated { agent: agent.name().to_owned() };
365	                match agent.run(child, input.clone()).instrument(span.clone()).await {
366	                    Ok(s) => tagged.push(Box::pin(s.map(move |ev| (i, ev)))),
367	                    Err(e) => {
368	                        let msg = e.to_string();
369	                        parent_failure.set(e);
370	                        span.record("otel.status_code", "ERROR");
371	                        yield AgentEvent::RunFailed { error: msg };
372	                        return;
373	                    }
374	                }
375	            }
376	
377	            let mut merged = futures_util::stream::select_all(tagged);
378	            let mut total = TokenUsage::default();
379	            let mut finals: Vec<String> = vec![String::new(); branches.len()];
380	            let mut completed: std::collections::BTreeMap<String, String> =
381	                std::collections::BTreeMap::new();
382	            let mut saw_failure = false;
383	
384	            while let Some((i, ev)) = merged.next().instrument(span.clone()).await {
385	                match ev {
386	                    AgentEvent::RunStarted { .. } => {}
387	                    AgentEvent::RunCompleted { usage } => {
388	                        total.add(usage);
389	                        let key = branches[i].0.clone();
390	                        ctx.state().set(key.clone(), finals[i].clone());
391	                        completed.insert(key, finals[i].clone());
392	                        // Each branch emits exactly one RunCompleted; fire
393	                        // OnSubagentStop for that branch's sub-agent here.
394	                        for hook in ctx.hooks().iter() {
395	                            let _ = hook
396	                                .on_event(&ctx, &crate::HookEvent::OnSubagentStop {
397	                                    agent: branches[i].1.name().to_owned(),
398	                                })
399	                                .await;
400	                        }
401	                    }
402	                    AgentEvent::RunFailed { .. } => {
403	                        saw_failure = true;
404	                        // A failed branch's sub-run is still complete; report it.
405	                        for hook in ctx.hooks().iter() {
406	                            let _ = hook
407	                                .on_event(&ctx, &crate::HookEvent::OnSubagentStop {
408	                                    agent: branches[i].1.name().to_owned(),
409	                                })
410	                                .await;
411	                        }
412	                    }
413	                    AgentEvent::MessageOutput { item } => {
414	                        if let Some(t) = assistant_text(&item) {
415	                            finals[i] = t;
416	                        }
417	                        yield AgentEvent::MessageOutput { item };
418	                    }
419	                    other => yield other,
420	                }
421	            }
422	
423	            let mut first_err: Option<AgentError> = None;
424	            for fh in &failures {
425	                if let Some(e) = fh.take() {
426	                    if first_err.is_none() {
427	                        first_err = Some(e);
