432	/// Serialize an event for a `CUSTOM` frame's `value`, degrading to `null` rather than
433	/// failing — a frame with a null value still tells the client the event happened.
434	fn to_value(ev: &AgentEvent) -> Value {
435	    serde_json::to_value(ev).unwrap_or(Value::Null)
436	}
