438	/// Concatenate the text blocks of a content list, ignoring non-text parts.
439	fn text_of(content: &[ContentPart]) -> String {
440	    content
441	        .iter()
442	        .filter_map(|c| match c {
443	            ContentPart::Text { text } => Some(text.as_str()),
444	            _ => None,
445	        })
446	        .collect()
447	}
